import{newSpecPage}from"@stencil/core/testing";import{ScPhoneInput}from"../sc-phone-input";describe("sc-phone-input",(()=>{it("ships a default pattern that is valid under the RegExp v flag and validates phone characters",(()=>{const e=(new ScPhoneInput).pattern;expect((()=>new RegExp(e,"v"))).not.toThrow(),expect((()=>new RegExp(e))).not.toThrow();const t=new RegExp(`^(?:${e})$`,"v");["(555)123-4567","+1 (555) 123-4567","555.123.4567","555-1234 ext 12","+44 20 7123 4567 x22","555-1234,,101"].forEach((e=>{expect(t.test(e)).toBe(!0)})),["!!!!","555*1234","555@1234"].forEach((e=>{expect(t.test(e)).toBe(!1)}))})),it("renders",(async()=>{const e=await newSpecPage({components:[ScPhoneInput],html:"<sc-phone-input></sc-phone-input>"});expect(e.root).toMatchSnapshot()}))}));